WITH flagged AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS session_start_flag FROM payments), sessions_payments AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT id, amount, paid_at, status, session_start_flag, island_id, CASE WHEN status RLIKE '^(SUCCESS|REFUNDED)$' THEN 'GROUP_B' WHEN status RLIKE '^(FAILED)$' THEN 'CORE' ELSE 'OTHER_ZONE' END AS status_zone FROM sessions_payments ORDER BY status DESC NULLS LAST;
